    "page.check.privacyTitle1": "உங்கள் தனியுரிமையை நாங்கள் பாதுகாக்கிறோம்",
    "page.check.privacyBody1": "உங்கள் பெயர் மற்றும் தொலைபேசி எண்ணை முதலில் உங்கள் சாதனத்திலேயே அகற்றுகிறோம். சுத்தமான, பாதுகாப்பான உரை மட்டுமே மோசடிக்கு சரிபார்க்கப்படுகிறது.",
