    "page.settings.display": "காட்சி",
    "page.settings.language": "மொழி தேர்வு",
    "page.settings.howWeProtect": "நாங்கள் உங்களை எவ்வாறு பாதுகாக்கிறோம்",
    "page.settings.howWeProtectBody": "எந்த செய்தியும் எங்கள் AI க்கு அனுப்பப்படும் முன், உங்கள் தொலைபேசி எண்கள் (9876543210) போன்றவை [PHONE_HIDDEN] போன்ற உரையால் மாற்றப்படும். இது உங்கள் போனில் நடக்கிறது, சேவையகத்தில் அல்ல.",
