    "page.results.badge": "ஆபத்து: மோசடியாக இருக்கலாம்",
    "page.results.title": "மோசடி சரிபார்ப்பு முடிவு",
    "page.results.verdict": "இந்தச் செய்தி உங்கள் பணம் அல்லது தனிப்பட்ட தகவல்களை வழங்கச் செய்வதற்காக ஏமாற்ற முயற்சிக்கிறது.",
    "page.results.riskScore": "ஆபத்து மதிப்பெண்",
    "page.results.score.high": "அதிக ஆபத்து",
    "page.results.score.medium": "நடுத்தர ஆபத்து",
    "page.results.score.low": "குறைந்த ஆபத்து",
    "page.results.redactedItems": "மறைக்கப்பட்ட விவரங்கள்",
    "page.results.redactedYes": "தானாக மறைக்கப்பட்டது",
    "page.results.redactedNo": "எதுவும் தேவையில்லை",
    "page.results.threatType": "அச்சுறுத்தல் வகை",
    "page.results.threatUnknown": "பொது சரிபார்ப்பு",
    "page.results.why": "இது ஏன் ஒரு மோசடி?",
    "page.results.reason.urgency": "கணக்கு மூடுதல் அல்லது இணைப்பு துண்டிப்பு போன்ற அச்சுறுத்தல்களால் அனுப்புபவர் உங்களை அவசரப்படுத்த முயற்சிக்கிறார். உண்மையான நிறுவனங்கள் இப்படி அழுத்தம் கொடுக்காது.",
    "page.results.reason.otp_request": "அனுப்புபவர் உங்கள் ஒரு-முறை கடவுச்சொல்லைக் கேட்கிறார். உங்கள் OTP உள்ளவர் உங்கள் கணக்கைக் கைப்பற்ற முடியும், எனவே உண்மையான சேவைகள் அதை ஒருபோதும் கேட்காது.",
    "page.results.reason.screen_share_request": "அனுப்புபவர் ஒரு செயலியை நிறுவ அல்லது திரையைப் பகிரச் சொல்கிறார். அது உங்கள் சாதனம் மற்றும் பணத்தின் கட்டுப்பாட்டை அவர்களுக்குத் தரும்.",
    "page.results.reason.suspicious_link": "செய்தியில் உள்ள இணைப்பு அல்லது QR குறியீடு போலி இணையதளத்திற்குச் செல்கிறது, உண்மையான நிறுவனத்திற்கு அல்ல.",
    "page.results.reason.impersonation": "அனுப்புபவர் உங்கள் நம்பிக்கையைப் பெற வங்கி, அரசு, கூரியர் அல்லது தொலைத்தொடர்பு அதிகாரி போல நடிக்கிறார்.",
    "page.results.reason.suspicious_collect_request": "அனுப்புபவர் கட்டணத்தை ஒப்புக்கொள்ள அல்லது பரிசு/பணத்திருப்பு பெறச் சொல்கிறார். இந்த தந்திரங்கள் உங்கள் பணம் அல்லது தரவை எடுப்பதற்காக உருவாக்கப்பட்டவை.",
    "page.results.safety": "பாதுகாப்பு: உங்கள் மறைக்கப்பட்ட தரவு",
    "page.results.sample": "\"அன்புள்ள வாடிக்கையாளரே, இன்று இரவு 9:30 மணிக்குள் உங்கள் மின்சாரம் துண்டிக்கப்படும். இணைப்பில் நிலையைப் புதுப்பிக்கவும். கணக்கு எண் ****4521. [REDACTED VALUE] நிலுவை. சரிபார்க்க OTP *** *** பயன்படுத்தவும்.\"",
