    "page.help.faq1.a": "செய்தியைச் சரிபார்ப்பது எளிது. நீங்கள் பெற்ற செய்தியை நகலெடுத்து முகப்புத் திரையின் \"செய்தியை சரிபார்\" பெட்டியில் ஒட்டவும். எங்கள் அமைப்பு உடனே தந்திரங்களைச் சரிபார்க்கும்.",
