    "page.help.faq3.q": "ரிடாக்ஷன் என்றால் என்ன",
    "page.help.faq3.a": "ரிடாக்ஷன் என்றால் உங்கள் தனிப்பட்ட விவரங்களை மறைப்பது. செய்தியைச் சரிபார்ப்பதற்கு முன், எங்கள் ஆப் உங்கள் தொலைபேசி எண், வங்கிக் கணக்குகள் மற்றும் OTP-களை தானாக மறைக்கிறது. உங்கள் தனிப்பட்ட தகவலை யாரும் பார்ப்பதில்லை.",
    "page.help.faq4.q": "அவசர தொடர்புகள்",
    "page.help.faq4.a": "நீங்கள் மோசடிக்கு ஆளாகிவிட்டீர்கள் என்று நினைத்தால், உடனடியாக உங்கள் வங்கி மற்றும் தேசிய உதவி எண் 1930-ஐ அழைக்கவும். இந்த எண்களை உங்கள் பாதுகாப்பு சுயவிவரத்தின் \"குடும்ப தொடர்புகள்\" பிரிவில் காணலாம்.",
