    "page.help.faq2.badgeSafe": "নিরাপদ",
    "page.help.faq2.safe": "আমরা কোনো প্রতারণা খুঁজে পাইনি। এটি পড়া নিরাপদ।",
    "page.help.faq3.q": "রেডাকশন কী",
    "page.help.faq3.a": "রেডাকশন মানে আপনার ব্যক্তিগত বিবরণ লুকানো। বার্তা যাচাই করার আগে আমাদের অ্যাপ আপনার ফোন নম্বর, ব্যাংক অ্যাকাউন্ট এবং OTP স্বয়ংক্রিয়ভাবে ঢেকে দেয়। আপনার ব্যক্তিগত তথ্য কেউ দেখে না।",
    "page.help.faq4.q": "জরুরি যোগাযোগ",
    "page.help.faq4.a": "যদি মনে হয় আপনি প্রতারণার শিকার হয়েছেন, সঙ্গে সঙ্গে আপনার ব্যাংক এবং জাতীয় হেল্পলাইন 1930-এ কল করুন। এই নম্বরগুলো আপনার সুরক্ষা প্রোফাইল পৃষ্ঠার \"পরিবারের যোগাযোগ\" অংশে পাবেন।",
    "page.help.faq5.q": "আজকের সাধারণ প্রতারণা",
    "page.help.faq5.a1": "বিদ্যুৎ বিল বিচ্ছিন্ন করার হুমকি।",
    "page.help.faq5.a2": "টাকা চাওয়ার ভুয়া পারিবারিক জরুরি অবস্থা।",
    "page.help.faq5.a3": "\"ছোট ফি\" চাওয়া লটারি জয়।",
